"""Generate the sorted WHATWG character-reference table from entities.json."""

import json
import pathlib
import sys

source = pathlib.Path(sys.argv[1])
target = pathlib.Path(__file__).resolve().parents[1] / "src/html/tokenizer/entities.rs"
entries = json.loads(source.read_text())
lines = [
    "// Generated by tools/generate_entities.py from https://html.spec.whatwg.org/entities.json.",
    "// WHATWG HTML data, licensed under CC BY 4.0: https://creativecommons.org/licenses/by/4.0/",
    "pub(super) static ENTITIES: &[(&str, &str)] = &[",
]
for name, entry in sorted(entries.items()):
    value = "".join(f"\\u{{{codepoint:x}}}" for codepoint in entry["codepoints"])
    lines.append(f'    ("{name[1:]}", "{value}"),')
lines.append("];")
target.write_text("\n".join(lines) + "\n")
